WITH with_dims AS (SELECT a.*, p2.status, p2.balance, p2.opened_date FROM transactions a LEFT JOIN accounts p2 ON a.account_id = p2.id), enriched AS (SELECT e.*, a.account_type, a.opened_date AS account_opened_date, a.balance AS account_balance FROM with_dims e LEFT JOIN accounts a ON e.account_id = a.id), with_dims_transactions AS (SELECT a.*, p.opened_date AS account_opened_date_2 FROM enriched a LEFT JOIN accounts p ON a.account_id = p.id), ranked AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY account_type, status ORDER BY account_balance DESC) AS dedup_rank FROM with_dims_transactions) ranked WHERE dedup_rank = 1), deduped AS (SELECT * FROM ranked QUALIFY ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY account_opened_date DESC NULLS LAST, id) = 1), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY account_id ORDER BY dedup_rank, id) AS dedup_rank_2 FROM deduped) ranked WHERE dedup_rank_2 = 1), with_dims_transactions_2 AS (SELECT s.*, b.opened_date AS account_opened_date_3 FROM latest s JOIN accounts b ON s.account_id = b.id) SELECT id, account_id, txn_type, txn_time, merchant, is_flagged, status, balance, opened_date FROM with_dims_transactions_2
